[business_research] {
  "normative_analysis": {
    "target_level": "Extra Large (特大型馆)",
    "compliance_source": "《科学技术馆建设标准》(建标 101-2007)",
    "suggested_area_range": "4,000–6,000 sqm",
    "standard_ratio_text": "业务研究用房: 10.0-15.0% (4000-6000 m²); 管理保障用房: 10.0-15.0% (4000-6000 m²)",
    "mandatory_sub_functions": [
      "设计研究室",
      "展品制作维修车间",
      "图书资料室",
      "技术档案室",
      "声像制作室",
      "展(藏)品和材料库",
      "办公室",
      "会议室",
      "接待室",
      "值班室",
      "警卫室",
      "食堂",
      "水、电、暖、空调、通讯设备用房"
    ]
  },
  "empirical_highlights": [
    {
      "feature_name": "分子生物学与主题实验室体系",
      "case_source": "National Pavilion of Biodiversity",
      "description": "建立专门的分子生物学实验室及用于科学研究的主题实验室，配套策展办公室与专业咨询空间，旨在支持生物研究所档案的保存及对拉丁美洲最大规模生物标本的科学研究。"
    },
    {
      "feature_name": "科研与展陈独立流线设计",
      "case_source": "Hacettepe University- Museum and Center For Biodiversity",
      "description": "为科研设施（含实验室、科学家办公室、藏品库）与博物馆展示空间设置相对独立的出入口，两者隔广场相望，在保证科研工作私密性与独立性的同时，维持各功能区在物理空间上的关联。"
    },
    {
      "feature_name": "非公众功能集约化分区",
      "case_source": "MUSE",
      "description": "将行政办公、科学实验室及员工辅助空间等非对公开放的功能集中布置于首个建筑结构中，实现后勤科研区与公共游览区的明确分区，确保运营效率。"
    },
    {
      "feature_name": "产学研协同创新中心",
      "case_source": "Shenzhen Science and Technology Museum",
      "description": "规划5400平方米的研究实验室与创新中心，旨在与区域内的科技产业、高校及研究机构建立合作，将博物馆打造为孵化创新与展示前沿科研成果的综合平台。"
    },
    {
      "feature_name": "垂直堆叠式库房与差异化环境控制",
      "case_source": "Moscow Polytechnic Museum and Educational Center Competition Entry",
      "description": "将后勤功能、办公室及藏品库房高效堆叠布置于展厅与后勤电梯之间；科研空间配备高等级气候环境控制系统，而办公区域则采用被动式控制系统，实现能源利用的差异化与最优化。"
    },
    {
      "feature_name": "展研一体化多功能空间",
      "case_source": "Museum of Tomorrow",
      "description": "设立“明日观测站”作为技术与科学研究空间，并将其直接融入博物馆展览体系中；该空间结构具有高度的功能通用性，可灵活转换为会议场所或科研工作区。"
    }
  ],
  "space_program_suggestion": {
    "core_zones": [
      "行政办公区",
      "科研与实验区",
      "藏品库房与库前区",
      "展陈修复与制作工坊",
      "设备与后勤支撑"
    ],
    "adjacency_requirements": "科研/修复与库房保持同层邻近；库房需靠近货梯与卸货口；安保/监控与库房同轴布局；对公众开放的可视化库房需设置导览与防火分隔。"
  }
}
